# -*- coding: utf-8 -*-
"""Tier1 상세설명 + 거리(광년) 데이터: 메시에 목록 (M1-M110).
거리는 문헌상 널리 쓰이는 근사값이며, 아주 먼 은하는 측정 오차가 크다.
"""

MESSIER = {
    "M1": (6500, "1054년 중국·아라비아 천문학자들이 관측한 초신성 폭발(SN 1054)의 잔해로, 1758년 샤를 메시에가 목록 1번으로 등재하며 메시에 목록의 시작이 됐다. 중심에는 초당 30회 자전하는 펄서가 있고, 성운은 지금도 초당 약 1,500km 속도로 팽창하고 있다. 1840년대 윌리엄 파슨스가 그린 스케치가 게 다리를 닮아 '게 성운'이라는 이름이 붙었다."),
    "M2": (37500, "1746년 장 도미니크 마랄디가 발견하고 1760년 메시에가 재발견해 목록에 올린 구상성단이다. 지름 약 175광년에 15만 개 이상의 별이 중력으로 뭉쳐 있으며, 우리 은하에서 가장 크고 밀집된 구상성단 중 하나로 꼽힌다. 나이는 약 130억 년으로 추정되어 우리 은하에서 가장 오래된 천체 중 하나다."),
    "M3": (33900, "1764년 샤를 메시에가 발견한 구상성단으로, 약 50만 개의 별을 포함하며 알려진 변광성이 274개 이상으로 구상성단 중 가장 많다. 나이는 약 114억 년으로 추정되며, 봄철 큰곰자리와 목동자리 사이에서 소형 망원경으로도 또렷하게 관측된다."),
    "M4": (7200, "1746년 필리프 로이 드 셰소가 발견한 구상성단으로, 지구에서 가장 가까운 구상성단 중 하나다. 중심부에 막대 모양으로 늘어선 별들이 특징이며, 1987년에는 태양보다 젊은 백색왜성이 다수 발견되어 화제가 됐다. 안타레스에서 매우 가까운 위치에 있어 여름철 전갈자리 관측 시 함께 찾기 좋다."),
    "M5": (24500, "1702년 고트프리트 키르히가 발견하고 1764년 메시에가 목록화한 구상성단으로, 나이가 약 130억 년에 달해 우리 은하에서 가장 오래된 성단 중 하나로 꼽힌다. 지름 약 165광년에 걸쳐 별 10만 개 이상이 밀집해 있으며, 뱀자리 방향에서 관측된다."),
    "M6": (1600, "산개성단으로, 밝은 별들의 배열이 날개를 펼친 나비 모양과 닮아 '나비 성단'이라는 별칭을 얻었다. 나이는 약 1억 년으로 비교적 젊고, 가장 밝은 별인 BM 스코르피이는 노란색 초거성으로 쌍안경에서도 색 차이가 확인된다. 여름철 전갈자리 꼬리 부근에서 볼 수 있다."),
    "M7": (980, "프톨레마이오스가 서기 130년경 이미 기록한 가장 오래된 성단 관측 사례 중 하나로 '프톨레마이오스 성단'이라 불린다. 나이는 약 2억 년이며, 맨눈으로도 흐릿한 별무리로 보일 만큼 밝고 가까워 여름철 전갈자리 꼬리 근처 관측 대상으로 인기가 많다."),
    "M8": (4100, "석호 모양의 암흑성운 띠가 성운을 가로지르는 것이 특징인 발광성운으로, 내부의 젊은 산개성단 NGC 6530과 함께 활발한 별 탄생 지역을 이룬다. 궁수자리 방향에 있으며 여름철 은하수 관측의 대표적인 대상이다."),
    "M9": (25800, "1764년 메시에가 발견한 구상성단으로, 은하 중심 방향에 가까워 성간 물질에 의한 빛의 감쇠(적화)가 뚜렷하게 나타난다. 나이는 약 120억 년으로 추정되며, 뱀주인자리 방향에서 여름철에 관측하기 좋다."),
    "M10": (14300, "1764년 메시에가 발견한 구상성단으로, 뱀주인자리에서 M12와 함께 쌍을 이루듯 나란히 위치해 비교 관측 대상으로 자주 언급된다. 중심부 별들이 비교적 느슨하게 분포해 중간 정도의 밀집도를 보인다."),
    "M11": (6200, "밀집한 별의 형태가 날아가는 오리 떼를 닮았다 하여 '야생오리 성단'으로 불리는 산개성단이다. 1681년 고트프리트 키르히가 발견했고, 약 2,900개의 별로 이뤄져 산개성단 중에서도 매우 풍부한 별 개수를 자랑한다. 방패자리 방향, 여름철 은하수 속에서 쌍안경으로도 쉽게 찾을 수 있다."),
    "M12": (15700, "1764년 메시에가 발견한 구상성단으로, 중심부의 별 밀도가 비교적 낮아 '느슨한' 구상성단으로 분류된다. 과거 은하 중심을 지나며 바깥쪽 별들을 다수 잃은 것으로 추정되며, 뱀주인자리 방향에서 M10과 함께 관측하기 좋다."),
    "M13": (22200, "'헤르쿨레스 대성단'으로 불리는 북반구 최대의 구상성단으로, 1714년 에드먼드 핼리가 발견했다. 약 30만 개의 별이 지름 145광년 공간에 밀집해 있으며, 1974년에는 외계 생명체를 향한 아레시보 메시지가 이 성단 방향으로 발사되기도 했다."),
    "M14": (30300, "1764년 메시에가 발견한 구상성단으로, 다른 구상성단보다 다소 어둡고 관측이 까다롭다. 1938년에는 이 성단 안에서 신성(nova) 폭발이 관측된 드문 사례로 알려져 있으며, 뱀주인자리 방향에 있다."),
    "M15": (33600, "1746년 장 도미니크 마랄디가 발견한 구상성단으로, 중심부가 극도로 밀집한 '핵붕괴(core-collapse)' 구상성단의 대표적인 예다. 100개 이상의 변광성과 여러 개의 펄서, 행성상성운 Pease 1을 포함하고 있어 구상성단 내부 진화 연구에 중요한 대상이다."),
    "M16": (5700, "젊은 산개성단과 그 별들을 탄생시킨 발광성운이 함께 있는 '성운+성단' 천체로, 성운 내부의 거대한 기둥 모양 성간물질 '창조의 기둥'은 1995년 허블 우주망원경 사진으로 유명해졌다. 뱀자리 방향, 여름철 은하수 속에 위치한다."),
    "M17": (5500, "백조 또는 말굽 모양으로 보여 '오메가 성운', '백조 성운' 등 다양한 별칭을 가진 발광성운이다. 1745~46년 장 필리프 드 셰조가 발견했으며, 내부에 수백 개의 젊고 뜨거운 별이 숨어 있어 우리 은하에서 가장 활발한 별 탄생 지역 중 하나로 꼽힌다."),
    "M18": (4900, "1764년 메시에가 발견한 비교적 작고 느슨한 산개성단으로, 나이는 약 3,200만 년의 젊은 성단이다. M17 오메가 성운 바로 옆에 있어 두 천체를 함께 관측하는 경우가 많다."),
    "M19": (28700, "1764년 메시에가 발견한 구상성단으로, 은하 중심 방향의 강한 조석력 때문에 구형이 아닌 눈에 띄게 타원형으로 찌그러진 형태를 보이는 것이 특징이다. 알려진 구상성단 중 가장 편평한 축비를 가진 성단으로 꼽힌다."),
    "M20": (5200, "붉은 발광성운, 푸른 반사성운, 검은 암흑성운 세 종류가 한 천체 안에 공존해 '삼렬 성운'이라는 이름이 붙었다. 1764년 메시에가 발견했으며, 궁수자리 방향에서 여름철 대표적인 성운 관측 대상이다."),
    "M21": (4250, "1764년 메시에가 삼렬 성운(M20)을 관측하다 함께 발견한 산개성단으로, 나이가 약 460만 년에 불과해 매우 젊은 별들로 구성돼 있다. 궁수자리 방향에서 M20과 가까이 위치한다."),
    "M22": (10600, "1665년경 아브라함 이일이 처음 기록한 것으로 알려진 구상성단으로, 지구에서 관측 가능한 구상성단 중 가장 밝은 것 중 하나다. 내부에 행성상성운 후보 두 개가 발견되어 구상성단에서는 매우 드문 사례로 주목받았다."),
    "M23": (2150, "1764년 메시에가 발견한 산개성단으로, 약 150개의 별이 비교적 고르게 분포해 있다. 나이는 약 3억 년으로 추정되며, 궁수자리 방향 여름철 은하수 속에서 쌍안경 관측에 적합하다."),
    "M24": (10000, "'궁수자리 별구름'이라 불리는 이 천체는 성단이 아니라 우리 은하 나선팔의 별들이 상대적으로 성간 물질이 적은 창(window)을 통해 겹쳐 보이는 영역이다. 육안으로도 은하수 속 유난히 밝은 구름처럼 보이며, 메시에 목록 중 가장 독특한 성격의 천체로 꼽힌다."),
    "M25": (2000, "1745년경 장 필리프 드 셰조가 처음 기록한 산개성단으로, 메시에 목록 중 드물게 세페이드 변광성(U Sagittarii)을 포함하고 있다. 궁수자리 방향에서 쌍안경으로도 쉽게 별들이 흩어져 보인다."),
    "M26": (5000, "1764년 메시에가 발견한 산개성단으로, 중심부에 상대적으로 별이 적은 공백 지역이 있는 것이 특징이다. 방패자리 방향에 위치하며 비교적 어두워 안시 관측보다는 사진 촬영에서 더 잘 드러난다."),
    "M27": (1360, "행성상성운 중 가장 먼저 발견된 천체로, 1764년 메시에가 발견했다. 태양과 비슷한 별이 죽어가며 바깥층 가스를 우주로 날려 보내는 마지막 단계를 보여주며, 그 모습이 아령을 닮아 '아령 성운'이라 불린다. 여우자리 방향, 여름부터 가을까지 관측하기 좋다."),
    "M28": (18600, "1764년 메시에가 발견한 구상성단으로, 우리 은하에서 처음으로 밀리세컨드 펄서가 발견된 구상성단이라는 점에서 천문학적으로 중요한 의미를 갖는다. 궁수자리 방향에 있다."),
    "M29": (4000, "1764년 메시에가 발견한 산개성단으로, 실제 성간 물질에 의한 빛 감쇠가 커서 겉보기보다 훨씬 더 멀고 밝은 별들로 이루어져 있다. 백조자리 방향 여름철 은하수 속에서 관측된다."),
    "M30": (27100, "1764년 메시에가 발견한 구상성단으로, 중심부 밀도가 매우 높은 핵붕괴형 구상성단에 속한다. 염소자리 방향에 있으며 가을철 관측 대상으로 알려져 있다."),
    "M31": (2500000, "지구에서 맨눈으로 볼 수 있는 가장 먼 천체로, 서기 964년 페르시아 천문학자 알수피가 '작은 구름'으로 처음 기록했다. 우리 은하보다 약 1.5~2배 큰 나선은하로, 약 45억 년 후 우리 은하와 충돌해 합쳐질 것으로 예측된다. 가을철 안드로메다자리에서 쉽게 찾을 수 있는 대표적인 심우주 대상이다."),
    "M32": (2500000, "안드로메다 은하(M31)의 위성 왜소 타원은하로, 1749년 기 조제프 드 이지오 드 이지가 발견했다. 은하핵 근처에 위치해 관측 시 M31의 광채와 겹쳐 보이는 경우가 많으며, 강한 조석력으로 바깥쪽 별들을 잃은 것으로 추정된다."),
    "M33": (2730000, "국부은하군에서 세 번째로 큰 은하이자, 안드로메다 은하(M31) 다음으로 맨눈 관측이 가능한 가장 먼 천체로 알려져 있다. 1764년 메시에가 독립적으로 발견해 목록화했으며, 삼각형자리 방향에서 어두운 하늘이 필요한 도전적인 관측 대상이다."),
    "M34": (1500, "1764년 메시에가 목록화했지만 그보다 앞서 조반니 바티스타 호디에르나가 1654년 이전 기록한 것으로 알려진 산개성단이다. 나이는 약 2억 년이며, 페르세우스자리 방향에서 쌍안경으로도 여러 별이 흩어져 보인다."),
    "M35": (2800, "1745년 필리프 로이 드 셰조가 발견한 산개성단으로, 약 2,500개의 별을 포함한 풍부한 성단이다. 나이는 약 1억 년으로 추정되며, 쌍둥이자리 방향 겨울철 관측 대상으로 인기가 많다."),
    "M36": (4100, "1764년 메시에가 목록화한 산개성단으로, 나이가 약 2,500만 년에 불과해 뜨겁고 젊은 별들로 구성돼 있다. 마차부자리 방향에서 M37, M38과 함께 '마차부자리 삼중 성단'으로 불린다."),
    "M37": (4500, "마차부자리의 세 산개성단 중 가장 밝고 별이 풍부한 성단으로, 약 500개의 별을 포함한다. 나이는 약 3억 년으로 추정되며, 중심부에 붉은 거성 하나가 눈에 띄게 자리하고 있다."),
    "M38": (4200, "마차부자리 삼중 성단 중 하나로, 별의 배열이 십자 또는 그리스 문자 파이(π) 모양과 닮아 알려져 있다. 나이는 약 2억 2천만 년으로 추정된다."),
    "M39": (825, "1750년경 기욤 르 장티가 발견한 것으로 알려진 매우 가깝고 느슨한 산개성단으로, 나이는 약 3억 년이다. 백조자리 방향에 있으며 넓게 퍼져 있어 쌍안경이나 저배율 망원경 관측에 적합하다."),
    "M40": (510, "메시에 목록 중 유일하게 성단이나 성운이 아닌 이중성으로, 1764년 메시에가 성운으로 오인해 목록에 올렸다가 실제로는 단순한 두 별의 배열임이 밝혀졌다. 큰곰자리 방향에 위치한다."),
    "M41": (2300, "프톨레마이오스 시대부터 알려졌을 것으로 추정되는 산개성단으로, 큰개자리 시리우스에서 남쪽으로 4도 떨어진 위치에 있다. 나이는 약 2억 년이며 겨울철 맨눈으로도 흐릿하게 확인된다."),
    "M42": (1344, "맨눈으로도 보이는 가장 밝은 발광성운으로, 오리온자리 벨트 아래 위치해 겨울철 대표적인 관측·촬영 대상이다. 내부의 트라페지움 다중성계에서 지금도 활발히 새로운 별들이 태어나고 있으며, 지구에서 가장 가까운 대규모 별 탄생 지역이다."),
    "M43": (1600, "오리온 대성운(M42)의 일부이지만 어두운 통로로 분리돼 별도 천체로 분류되며, 발견자 장자크 드 메랑의 이름을 따 '드 메랑 성운'이라 불린다. 중심에 있는 젊은 별 NU 오리오니스가 성운을 밝히고 있다."),
    "M44": (577, "고대부터 '작은 구름'으로 알려졌던 산개성단으로, 갈릴레오가 1609년 망원경으로 처음 개개의 별로 분해해 관측했다. 별들이 밀집한 모습이 벌집을 닮아 '벌집 성단'이라 불리며, 게자리 방향 봄철 대표 관측 대상이다."),
    "M45": (444, "'일곱 자매'라는 별칭으로 잘 알려진 플레이아데스 성단은 성경과 그리스 신화 등 여러 문화권 기록에 등장할 만큼 오래전부터 알려진 산개성단이다. 뜨겁고 젊은 별들 주위로 푸른 반사성운 가스가 감싸고 있어, 메시에 목록에서 성운으로 분류된 드문 산개성단이다."),
    "M46": (5500, "1771년 메시에가 발견한 산개성단으로, 내부에 겹쳐 보이는 행성상성운 NGC 2438이 함께 있어 흥미로운 시야를 제공한다. 이 행성상성운은 실제로는 성단보다 훨씬 가까이 위치한 우연한 겹침이다."),
    "M47": (1600, "M46 바로 옆에 위치한 밝고 젊은 산개성단으로, 나이는 약 7,800만 년이다. 1654년 이전 조반니 바티스타 호디에르나가 이미 기록했을 것으로 추정되며, 겨울철 외뿔소자리 방향에서 관측된다."),
    "M48": (1500, "1771년 메시에가 목록화했으나 좌표 오류로 오랫동안 정체가 불분명했던 산개성단이다. 나이는 약 4억 5천만 년으로 추정되며, 쌍안경으로도 여러 별이 흩어져 보이는 넓은 성단이다."),
    "M49": (56000000, "처녀자리 은하단에서 가장 먼저 발견된 은하로, 1771년 메시에가 목록화했다. 처녀자리 은하단에서 가장 밝은 은하 중 하나인 거대 타원은하로, 다수의 구상성단을 거느리고 있다."),
    "M50": (3200, "1772년경 메시에가 기록한 산개성단으로, 그보다 앞서 조반니 도메니코 카시니가 1711년 이전 발견했을 것으로 알려져 있다. 나이는 약 1억 4천만 년이며, 외뿔소자리 방향 겨울철 관측 대상이다."),
    "M51": (23000000, "나선팔이 뚜렷하게 드러나는 대표적인 '그랜드 디자인' 나선은하로, 동반은하 NGC 5195와 상호작용하며 '소용돌이 은하'라는 이름을 얻었다. 1845년 윌리엄 파슨스가 처음으로 은하의 나선 구조를 관측·스케치한 역사적인 천체이기도 하다."),
    "M52": (5000, "1774년 메시에가 발견한 산개성단으로, 나이는 약 3,500만 년으로 비교적 젊다. 카시오페아자리 방향에 있으며, 인근의 초신성 잔해 '거품 성운(NGC 7635)'과 함께 촬영되는 경우가 많다."),
    "M53": (58000, "1775년 요한 엘레르트 보데가 발견한 구상성단으로, 우리 은하 중심에서 매우 멀리 떨어진 외곽 헤일로에 위치한다. 머리털자리 방향에서 관측되며, 나이는 약 127억 년으로 추정된다."),
    "M54": (87400, "우리 은하에 속한 것이 아니라 궁수자리 왜소 구상은하(Sgr dSph)에 속하는 구상성단으로, 우리 은하가 이웃 왜소은하를 흡수하는 과정을 보여주는 중요한 증거로 여겨진다. 1778년 메시에가 발견했다."),
    "M55": (17600, "1752년 니콜라 루이 드 라카유가 아프리카 남단에서 발견한 구상성단으로, 비교적 느슨하게 별들이 분포해 있다. 궁수자리 방향에 있으며 남쪽 하늘에서 관측하기 좋다."),
    "M56": (32900, "1779년 메시에가 발견한 구상성단으로, 다른 구상성단에 비해 중심부 밀집도가 낮은 편이다. 거문고자리 방향, 여름철 은하수 인근에서 관측된다."),
    "M57": (2283, "행성상성운의 대표적인 예로, 태양과 비슷한 별이 죽음을 앞두고 바깥층 가스를 고리 모양으로 방출한 모습이다. 1779년 앙투안 다르퀴에가 발견했으며, 거문고자리 방향 여름철 대표 촬영 대상이다."),
    "M58": (62000000, "처녀자리 은하단에 속한 막대 나선은하로, 1779년 메시에가 발견했다. 활동성 은하핵을 가진 세이퍼트 은하로 분류되며, 지금까지 두 차례의 초신성이 관측됐다."),
    "M59": (60000000, "1779년 요한 고트프리트 쾰러가 처녀자리 은하단에서 발견한 타원은하로, 거의 동시에 메시에도 독립적으로 목록화했다. 자체적으로 반대 방향으로 도는 두 개의 별 무리가 존재하는 것이 특징이다."),
    "M60": (55000000, "처녀자리 은하단에 속한 거대 타원은하로, 1779년 쾰러가 발견했다. 이웃한 나선은하 NGC 4647과 상호작용하는 모습이 관측돼 은하 충돌 연구의 대상이 되기도 한다."),
    "M61": (55000000, "처녀자리 은하단에 속한 막대 나선은하로, 활발한 별 탄생과 여러 차례의 초신성 관측으로 유명하다. 1779년 바르나바 오리아니와 메시에가 거의 같은 시기에 독립적으로 발견했다."),
    "M62": (22200, "1771년 메시에가 발견한 구상성단으로, 중심부가 매우 밀집한 핵붕괴형 구조를 보인다. 뱀주인자리 방향에 있으며, 은하 중심 쪽으로 기울어진 비대칭 형태가 특징이다."),
    "M63": (27000000, "나선팔이 조각조각 흩어진 모습이 해바라기 씨앗을 닮아 '해바라기 은하'로 불린다. 1779년 피에르 메생이 발견했으며, 사냥개자리 방향에서 비교적 밝게 관측된다."),
    "M64": (24000000, "은하 중심을 가로지르는 두꺼운 암흑 띠 모양의 성간물질 때문에 '검은 눈 은하'라는 별칭을 얻었다. 1779년 에드워드 피고트가 발견했으며, 내부 가스가 은하 본체와 반대 방향으로 회전하는 독특한 구조가 있다."),
    "M65": (35000000, "사자자리 삼중 은하(M65, M66, NGC 3628)를 이루는 나선은하 중 하나로, 1780년 메시에가 발견했다. 먼지 띠가 뚜렷한 나선팔 구조를 갖고 있다."),
    "M66": (36000000, "사자자리 삼중 은하 중 가장 크고 밝은 나선은하로, 이웃 은하들과의 조석 상호작용으로 나선팔이 비대칭적으로 뒤틀려 있다. 1780년 메시에가 발견했다."),
    "M67": (2700, "산개성단 중 나이가 가장 많은 것으로 알려진 성단 중 하나로, 약 32억~50억 년에 달해 태양과 견줄 만큼 오래됐다. 게자리 방향에 있으며, 은하면에서 벗어난 위치 덕분에 파괴되지 않고 장수한 것으로 추정된다."),
    "M68": (33300, "1780년 메시에가 발견한 구상성단으로, 은하면에서 크게 벗어난 궤도를 돌아 다른 왜소은하에서 기원했을 가능성이 제기된다. 바다뱀자리 방향에 있다."),
    "M69": (29700, "1780년 메시에가 발견한 구상성단으로, 은하 중심에 비교적 가까워 무거운 원소 함량이 높은 편에 속한다. 궁수자리 방향에 있다."),
    "M70": (29400, "1780년 메시에가 발견한 구상성단으로, 1995년 인근에서 발견된 헤일-보프 彗星이 이 성단 부근을 지나며 함께 촬영돼 유명해졌다. 궁수자리 방향에 있다."),
    "M71": (13000, "오랫동안 구상성단인지 밀집 산개성단인지 논쟁이 있었을 만큼 밀집도가 낮은 구상성단으로, 1745년경 필리프 로이 드 셰조가 발견했다. 화살자리 방향에 있다."),
    "M72": (55000, "1780년 피에르 메생이 발견한 구상성단으로, 우리 은하에서 상당히 멀리 떨어진 외곽에 위치한다. 물병자리 방향에 있으며 비교적 어두워 도전적인 관측 대상이다."),
    "M73": (0, "실제로는 성단이 아니라 우연히 배열된 4개의 별로 이뤄진 애스터리즘으로, 1780년 메시에가 성운의 흔적으로 오인해 목록에 올렸다. 물병자리 방향에 있으며, 메시에 목록의 분류 오류를 보여주는 대표적 사례로 언급된다."),
    "M74": (32000000, "정면으로 보이는 대칭적인 나선팔 구조 때문에 '유령 은하'라는 별칭을 가진 은하로, 표면 밝기가 낮아 메시에 목록에서 관측이 가장 까다로운 천체로 꼽힌다. 1780년 피에르 메생이 발견했다."),
    "M75": (67500, "1780년 피에르 메생이 발견한 구상성단으로, 중심부가 매우 밀집한 핵붕괴형 구조를 가진다. 궁수자리 방향, 우리 은하 외곽에 위치한다."),
    "M76": (2500, "메시에 목록의 행성상성운 중 가장 어두운 천체로 '작은 아령 성운'이라는 별칭을 가진다. 1780년 피에르 메생이 발견했으며, 두 개의 겹쳐진 로브 구조가 나비 모양을 연상시킨다."),
    "M77": (47000000, "가장 밝은 세이퍼트 은하 중 하나로, 중심에 거대한 초질량 블랙홀이 활발히 물질을 흡수하며 강한 방사선을 내뿜는다. 1780년 피에르 메생이 발견했으며, 활동성 은하핵 연구의 대표적 대상이다."),
    "M78": (1600, "오리온자리 성운 복합체에 속한 반사성운으로, 젊은 별빛이 주변 성간 먼지에 반사되어 파랗게 빛난다. 1780년 피에르 메생이 발견했으며, 메시에 목록에서 순수 반사성운으로는 대표적인 예다."),
    "M79": (42100, "겨울철 남쪽 하늘의 토끼자리에 있는 흔치 않은 겨울철 구상성단으로, 1780년 피에르 메생이 발견했다. 우리 은하가 아닌 카니스 메이저 왜소은하에서 기원했을 가능성이 있다는 가설이 제기된 바 있다."),
    "M80": (32600, "1781년 메시에가 발견한 구상성단으로, 1860년 이 성단 안에서 신성이 폭발한 드문 관측 기록이 있다. 전갈자리 방향에 있다."),
    "M81": (11800000, "1774년 요한 엘레르트 보데가 발견해 '보데 은하'로도 불리는 큰 나선은하로, 이웃한 M82와 중력적으로 상호작용하며 두 은하 모두에서 활발한 별 형성을 유발하고 있다. 큰곰자리 방향, 북반구에서 사계절 관측 가능한 인기 대상이다."),
    "M82": (12000000, "M81과의 상호작용으로 폭발적인 별 탄생이 일어나 은하 중심에서 강한 초신성풍이 뿜어져 나오는 '스타버스트 은하'의 대표 사례다. 옆에서 본 모습이 시가처럼 길쭉해 '시가 은하'라는 별칭을 가진다."),
    "M83": (15000000, "우리 은하와 비슷한 막대 나선은하로, 지금까지 6차례의 초신성이 관측돼 알려진 나선은하 중 초신성 발생률이 가장 높은 은하로 꼽힌다. 남반구에서 잘 보여 '남쪽 바람개비 은하'라 불린다."),
    "M84": (60000000, "처녀자리 은하단 중심부의 '마르카리안 체인'을 이루는 거대 타원은하로, 1781년 메시에가 발견했다. 강한 전파를 방출하는 활동성 은하핵을 가지고 있다."),
    "M85": (60000000, "처녀자리 은하단에서 비교적 북쪽에 치우쳐 있는 렌즈형 은하로, 1781년 피에르 메생이 발견했다. 최근 이웃 은하와의 병합 흔적으로 추정되는 구조가 관측됐다."),
    "M86": (52000000, "마르카리안 체인에 속한 은하로, 처녀자리 은하단 은하들 중 지구를 향해 가장 빠르게 접근(청색이동)하는 특이한 운동을 보인다. 1781년 메시에가 발견했다."),
    "M87": (53000000, "처녀자리 은하단의 중심을 차지하는 초거대 타원은하로, 태양 질량의 65억 배에 달하는 초질량 블랙홀을 품고 있다. 2019년 사건지평선망원경(EHT)이 인류 최초로 블랙홀의 실제 그림자를 촬영한 은하로 역사에 남았다."),
    "M88": (47000000, "처녀자리 은하단에 속한 아름다운 나선은하로, 은하단 안을 고속으로 통과하며 성간 가스가 벗겨져 나가는 '램 압력 벗김' 현상을 겪고 있는 것으로 연구됐다. 1781년 메시에가 발견했다."),
    "M89": (50000000, "거의 완벽한 구형에 가까운 타원은하로, 1781년 메시에가 발견했다. 처녀자리 은하단에 속하며 넓은 별들의 헤일로가 은하 본체를 둘러싸고 있는 것이 관측됐다."),
    "M90": (59000000, "처녀자리 은하단에 속하지만 드물게 지구 쪽으로 접근하는(청색이동) 운동을 보이는 나선은하로, 은하단 중심 근처를 빠르게 지나는 과정에 있는 것으로 해석된다. 1781년 메시에가 발견했다."),
    "M91": (63000000, "막대 나선은하로, 1781년 메시에가 발견한 뒤 오랫동안 정체 불명 천체로 남아 있다가 1969년에야 정확한 정체가 재확인된 흥미로운 이력을 가진다. 처녀자리 은하단에 속한다."),
    "M92": (26700, "1777년 요한 엘레르트 보데가 발견한 구상성단으로, 나이가 약 132억 년에 달해 우주에서 가장 오래된 천체 중 하나로 꼽힌다. 헤르쿨레스자리에 있으며 M13에 비해 상대적으로 덜 알려져 있지만 밝기는 비슷하다."),
    "M93": (3600, "1781년 메시에가 발견한 산개성단으로, 삼각형 또는 나비 모양의 별 배열이 특징이다. 용골자리 방향에 있으며 나이는 약 1억 년으로 추정된다."),
    "M94": (16000000, "안쪽에 별 형성이 활발한 고리 구조가 있고 바깥쪽은 상대적으로 조용한 이중 구조를 가진 나선은하로, 1781년 피에르 메생이 발견했다. 사냥개자리 방향에 있다."),
    "M95": (33000000, "막대 나선은하로, 막대 구조 양 끝에서 강한 별 탄생 고리가 형성되어 있는 것이 특징이다. 1781년 메생이 발견했으며 2012년 초신성이 관측됐다."),
    "M96": (31000000, "사자자리 은하군의 중심을 이루는 나선은하로, 1781년 메생이 발견했다. 비대칭적인 나선팔 구조는 이웃 은하들과의 과거 상호작용 흔적으로 추정된다."),
    "M97": (2030, "둥근 모양에 두 개의 어두운 반점이 있어 부엉이 눈처럼 보인다 하여 '부엉이 성운'이라 불리는 행성상성운이다. 1781년 피에르 메생이 발견했으며, 큰곰자리 방향에 있다."),
    "M98": (44000000, "처녀자리 은하단에 속한 나선은하로, 은하단 은하 중 드물게 청색이동을 보여 지구에 접근하고 있다. 1781년 피에르 메생이 발견했다."),
    "M99": (50000000, "정면으로 보이는 비대칭 나선팔 구조 때문에 '바람개비 은하'라는 별칭으로도 불리며, 이웃 은하와의 상호작용으로 나선팔 한쪽이 뒤틀려 있다. 1781년 피에르 메생이 발견했다."),
    "M100": (55000000, "처녀자리 은하단에서 가장 밝은 나선은하 중 하나로, 1781년 피에르 메생이 발견했다. 1995년 이 은하까지의 거리 측정은 허블 우주상수 연구의 핵심 데이터로 활용됐다."),
    "M101": (21000000, "정면으로 보이는 대표적인 '그랜드 디자인' 나선은하로 '바람개비 은하'라 불린다. 1781년 피에르 메생이 발견했으며, 큰곰자리 방향에서 넓게 퍼진 나선팔 구조가 특징이다."),
    "M102": (40000000, "처음 목록에 오를 때 정체가 불분명해 오랫동안 논쟁이 있었던 렌즈형 은하로, 현재는 옆에서 본 렌즈형 은하 NGC 5866으로 동일시된다. 두꺼운 먼지 띠가 은하 중앙을 가로지르는 모습이 특징이다."),
    "M103": (8000, "메시에 자신이 목록에 올린 마지막 천체 중 하나로, 1781년 피에르 메생이 발견한 산개성단이다. 카시오페아자리 방향에 있으며 비교적 젊은 별들로 구성돼 있다."),
    "M104": (29000000, "은하 중심을 두꺼운 먼지 띠가 감싸고 있어 멕시코 전통 모자를 닮았다는 뜻의 '솜브레로 은하'로 불린다. 거대한 헤일로에 약 2,000개의 구상성단을 거느리고 있어 은하 진화 연구에서 중요한 대상으로 꼽힌다."),
    "M105": (32000000, "사자자리 은하군에 속한 타원은하로, 은하 중심에 태양 질량의 2억 배에 달하는 초질량 블랙홀이 확인됐다. 1781년 피에르 메생이 발견했다."),
    "M106": (23000000, "은하 중심의 활동성 핵에서 뻗어 나오는 특이한 X선·전파 제트가 관측되는 나선은하로, 1781년 피에르 메생이 발견했다. 사냥개자리 방향에 있다."),
    "M107": (20900, "1782년 피에르 메생이 발견한 구상성단으로, 상대적으로 느슨한 밀집도를 가진다. 뱀주인자리 방향에 있으며 메시에가 마지막으로 추가한 천체 중 하나다."),
    "M108": (45000000, "거의 옆에서 보이는 나선은하로, 뚜렷한 나선팔 구조 없이 먼지 띠가 은하면을 가로지르는 모습이 특징이다. 큰곰자리 방향, 부엉이 성운(M97) 근처에 위치한다."),
    "M109": (55000000, "큰곰자리 방향의 막대 나선은하로, 메시에 목록에서 지구로부터 가장 먼 은하 중 하나로 꼽힌다. 뚜렷한 막대 구조 양 끝에서 나선팔이 뻗어 나온다."),
    "M110": (2690000, "안드로메다 은하(M31)의 위성 왜소 타원은하로, 1773년 메시에가 처음 관측했지만 목록에는 정식으로 포함되지 않았다가 1966년에야 뒤늦게 추가됐다. M32와 함께 안드로메다 은하 주변에서 관측된다."),
}
